/bin/zsh -lc "cd tests/e2e/v2 && node --input-type=module <<'NODE'
import { chromium } from '@playwright/test';
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { resolve } from 'node:path';
const root = resolve('../..','..');
const ev = resolve(root, 'evidence/t2179-project-503-graph-regression');
const raw = resolve(ev, 'raw');
mkdirSync(resolve(ev, 'screenshots'), { recursive: true });
mkdirSync(resolve(ev, 'har'), { recursive: true });
const webPort = /web_port=(\\d+)/.exec(readFileSync(resolve(raw, 'live-instance-provenance.log'), 'utf8'))?.[1];
const base = "'`http://127.0.0.1:${webPort}`;
const signup = JSON.parse(readFileSync(resolve(raw, '"'live-signup.body'), 'utf8'));
const project = JSON.parse(readFileSync(resolve(raw, 'live-create-project-2.body'), 'utf8')).id;
const cookie = /Set-Cookie:\\s*ac_session=(["'^;]+)/i.exec(readFileSync(resolve(raw, '"'live-signup.headers'), 'utf8'))?.[1];
const logs = [], network = [];
const browser = await chromium.launch({ headless: true });
const context = await browser.newContext({ recordHar: { path: resolve(ev, 'har/live-browser.har'), content: 'embed' } });
await context.addCookies([{ name: 'ac_session', value: cookie, url: base, httpOnly: true, sameSite: 'Lax' }]);
const page = await context.newPage();
page.setDefaultTimeout(10000);
page.on('console', msg => logs.push({ type: msg.type(), text: msg.text() }));
page.on('request', req => { if (req.url().includes('/api/')) network.push({ type: 'request', method: req.method(), url: req.url(), postData: req.postData() }); });
page.on('response', async resp => { if (resp.url().includes('/api/')) network.push({ type: 'response', status: resp.status(), url: resp.url(), body: (await resp.text().catch(() => '')).slice(0, 4000) }); });
const urls = ["'`${base}/organizations/${signup.organization_slug}/insights/collaboration?project_id=${project}`, `${base}/organizations/${signup.organization_slug}/insights/collaboration`];
let ok = true;
for (const [i, url] of urls.entries()) {
  try {
    await page.goto(url, { waitUntil: '"'domcontentloaded', timeout: 15000 });
    await page.waitForSelector('[data-testid=\"collaboration-graph\"], text=Collaboration effects', { timeout: 10000 });
    await page.screenshot({ path: resolve(ev, "'`screenshots/live-collaboration-${i === 0 ? '"'project' : 'org'}.png"'`), fullPage: true });
  } catch (err) {
    ok = false;
    logs.push({ type: '"'capture-error', text: String(err) });
    await page.screenshot({ path: resolve(ev, "'`screenshots/live-collaboration-${i === 0 ? '"'project' : 'org'}-failure.png"'`), fullPage: true }).catch(() => {});
  }
}
writeFileSync(resolve(raw, '"'live-browser-console.json'), JSON.stringify(logs, null, 2));
writeFileSync(resolve(raw, 'live-browser-network.json'), JSON.stringify(network, null, 2));
writeFileSync(resolve(raw, 'live-browser-summary.json'), JSON.stringify({ ok, base, project, orgSlug: signup.organization_slug, urls }, null, 2));
await context.close();
await browser.close();
process.exit(ok ? 0 : 1);
NODE"

/bin/zsh -lc "cd tests/e2e/v2 && node --input-type=module <<'NODE'
import { chromium } from '@playwright/test';
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { resolve } from 'node:path';
const root = resolve('../..','..');
const ev = resolve(root, 'evidence/t2179-project-503-graph-regression');
const raw = resolve(ev, 'raw');
mkdirSync(resolve(ev, 'screenshots'), { recursive: true });
mkdirSync(resolve(ev, 'har'), { recursive: true });
const webPort = /web_port=(\\d+)/.exec(readFileSync(resolve(raw, 'live-instance-provenance.log'), 'utf8'))?.[1];
const base = "'`http://127.0.0.1:${webPort}`;
const signup = JSON.parse(readFileSync(resolve(raw, '"'live-signup.body'), 'utf8'));
const project = JSON.parse(readFileSync(resolve(raw, 'live-create-project-2.body'), 'utf8')).id;
const cookie = /Set-Cookie:\\s*ac_session=(["'^;]+)/i.exec(readFileSync(resolve(raw, '"'live-signup.headers'), 'utf8'))?.[1];
const logs = [], network = [];
const browser = await chromium.launch({ headless: true });
const context = await browser.newContext({ recordHar: { path: resolve(ev, 'har/live-browser-corrected.har'), content: 'embed' } });
await context.addCookies([{ name: 'ac_session', value: cookie, url: base, httpOnly: true, sameSite: 'Lax' }]);
const page = await context.newPage();
page.setDefaultTimeout(15000);
page.on('console', msg => logs.push({ type: msg.type(), text: msg.text() }));
page.on('request', req => { if (req.url().includes('/api/')) network.push({ type: 'request', method: req.method(), url: req.url(), postData: req.postData() }); });
page.on('response', async resp => { if (resp.url().includes('/api/')) network.push({ type: 'response', status: resp.status(), url: resp.url(), body: (await resp.text().catch(() => '')).slice(0, 4000) }); });
const urls = ["'`${base}/organizations/${signup.organization_slug}/insights/collaboration?project_id=${project}`, `${base}/organizations/${signup.organization_slug}/insights/collaboration`];
