writeFileSync(resolve(raw, 'live-browser-console-corrected.json'), JSON.stringify(logs, null, 2));
writeFileSync(resolve(raw, 'live-browser-network-corrected.json'), JSON.stringify(network, null, 2));
writeFileSync(resolve(raw, 'live-browser-summary-corrected.json'), JSON.stringify({ ok: true, base, project, orgSlug: signup.organization_slug, results }, null, 2));
await context.close();
await browser.close();
NODE"

